function expandReadonlyNav(){var root=document.querySelector(".readonly"),head=root&&root.querySelector(".readHead");if(!root||!head||root.querySelector(".panelNav"))return;var labels=currentSharedRole==="User"?["Dashboard","My UPI Accounts","Collection / Usage","Deposits","Earned Commission","Withdraw Commission","GPay Details","History"]:["Dashboard","UPI Accounts","Collections","Settlement","Withdrawals","Charges","GPay Details","History"];var bar=document.createElement("div");bar.className="panelNav";labels.forEach(function(labelText){var b=document.createElement("button");b.className="btn ghost sm";b.textContent=labelText;b.onclick=function(){var key=labelText.toLowerCase();root.querySelectorAll(":scope > .box").forEach(function(box){box.style.display=key==="dashboard"?"":box.textContent.toLowerCase().indexOf(key.split(" ")[0])>=0?"":"none"});bar.querySelectorAll("button").forEach(function(x){x.classList.remove("primary")});b.classList.add("primary")};bar.appendChild(b)});head.after(bar)}
function sanitizeShareLinks(){var root=document.getElementById("shareBody");if(!root)return;root.querySelectorAll("input").forEach(function(input){if(/#(?:user|agent|merchant)=$/.test(input.value)||!input.value){input.value="Regeneration required";input.title="Regeneration required";var row=input.closest(".shareLine");if(row)row.querySelectorAll("button").forEach(function(button){if(/Copy|Open/.test(button.textContent))button.disabled=true})}})}
function nav(name,b){var aliases={accounts:"users",collections:"ledger",commission:"users",userWithdrawals:"ledger",merchantSettlement:"dashboard",merchantWithdrawals:"ledger",charges:"charges",frozen:"ledger",gpay:"users",history:"ledger",merchantGpay:"users",settlement:"dashboard",withdrawals:"ledger",usage:"ledger",earned:"dashboard",withdrawCommission:"dashboard"},target=aliases[name]||name;if(target==="charges")showChargesPage();document.querySelectorAll(".section").forEach(function(x){x.classList.remove("active")});var section=document.getElementById(target);if(section)section.classList.add("active");document.querySelectorAll(".nav button").forEach(function(x){x.classList.remove("active")});if(b)b.classList.add("active");var title=document.getElementById("title");if(title)title.textContent={dashboard:"Operations Dashboard",users:"Users / UPI Accounts",ledger:"Collections, Withdrawals and History",deposits:"Deposits",share:"Share Links",charges:"Merchant Charges"}[target]||name}
function showChargesPage(){var main=document.querySelector(".main");if(!main)return;var s=document.getElementById("charges");if(!s){s=document.createElement("section");s.id="charges";s.className="section";main.appendChild(s)}var rows=(db.merchantCharges||[]).map(function(c){return '<div class="entry"><div><b>'+money(c.amountInr)+'</b><div class="muted">'+dateFmt(c.date)+' · '+esc(c.reference||"No reference")+'</div></div><div><b>'+esc(c.userName)+'</b><div class="muted">'+esc(c.upiId||"UPI not recorded")+' · '+esc(c.mobile||"No mobile")+'<br>'+esc(c.note||"")+'</div></div><div>'+(c.status==="active"?'<button class="btn amber sm" onclick="SF.reverseMerchantCharge(\''+c.id+'\')">Reverse</button>':'<span class="badge">Reversed</span>')+'</div></div>'}).join("");s.innerHTML='<div class="toolbar"><div><h2>Merchant Charges</h2><div class="muted">Charges reduce available merchant settlement without changing collection history.</div></div><button class="btn primary" onclick="SF.addMerchantCharge()">Add Charge</button></div><div class="detailKpis">'+metric("Total Charges",money((db.merchantCharges||[]).filter(function(c){return c.status==="active"}).reduce(function(n,c){return n+c.amountInr},0)))+metric("Charge Records",(db.merchantCharges||[]).length)+metric("Available Settlement",money(Math.max(0,totals().collection-totals().frozen-totals().merchantSettled-(db.withdrawals||[]).filter(function(w){return w.requesterType==="merchant"&&["pending","paid"].includes(w.status)}).reduce(function(n,w){return n+w.amountInr},0))))+'</div>'+(rows||'<div class="empty">No charges</div>')}
function addMerchantCharge(){modal('<div class="modalBox"><div class="modalHead"><b>Add Merchant Charge</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+selectField("Related User","chargeProvider",db.users.filter(function(u){return u.status!=="deleted"}).map(function(u){return [u.id,u.name+" ("+u.id+")"]}),db.users[0]?.id||"")+field("Amount INR","chargeAmount","","number")+field("UPI Account ID (optional)","chargeUpi","")+field("UPI ID","chargeUpiId","")+field("Mobile","chargeMobile","")+field("Date","chargeDate",today(),"date")+field("Reference","chargeReference","")+field("Note","chargeNote","")+'</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveMerchantCharge()">Save Charge</button></div></div>')}
async function saveMerchantCharge(){var u=db.users.find(function(x){return x.id===v("chargeProvider")}),amount=Number(v("chargeAmount")||0);if(!u||amount<=0)return toast("User and positive amount required");try{await backend.addMerchantCharge({provider_id:u.remoteId,upi_account_id:v("chargeUpi")||null,amount_inr:amount,user_name:u.name,upi_id:v("chargeUpiId")||u.upi,mobile:v("chargeMobile")||u.mobile,charge_date:v("chargeDate")||today(),reference:v("chargeReference"),note:v("chargeNote"),idempotency_key:id("charge")});close();await refreshFromBackend();toast("Charge saved");showChargesPage()}catch(err){toast(err.message||"Charge failed")}}
