function addUser(){modal('<div class="modalBox small"><div class="modalHead"><div><b>Create User Card</b><div class="muted" style="font-size:12px">Name, Telegram and funding model are required.</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+field("User Name","newName","")+field("Telegram Username","newTg","")+selectField("Funding Model","newMode",[["deposit","Deposit Based"],["commission","Commission Based (3.5%)"]],"deposit")+'<div class="field full"><div class="notice green"><b>Deposit Based:</b> confirmed TRC20 USDT creates collection capacity at the configured deposit rate.<br><b>Commission Based:</b> Admin assigns the internal limit and the user earns commission on successful INR withdrawals.</div></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.createUser()">Create Card</button></div></div>')}
async function createUser(){var name=v("newName"),tg=v("newTg"),mode=v("newMode");if(!name||!tg)return toast("User Name and Telegram Username required");if(mode!=="deposit"&&mode!=="commission")return toast("Select Deposit Based or Commission Based");var n=1001+db.users.length;while(db.users.some(function(u){return u.id==="USR-"+n}))n++;var u={id:"USR-"+n,name:name,telegram:tg,upi:"",mobile:"",apk:"",gpayLogin:"",qrs:[],fundingMode:mode,limit:0,depositAddress:"",token:tok(),active:true};if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{var result=await backend.upsertProvider(u);u.remoteId=result.data&&result.data.id;close();toast((mode==="deposit"?"Deposit Based":"Commission Based")+" user card created");await refreshFromBackend()}catch(err){toast(err.message||"User creation failed")}return}db.users.push(u);audit("user_created",u.id,"Created with Name + Telegram • "+(mode==="deposit"?"Deposit Based":"Commission Based"),"admin");close();save();toast((mode==="deposit"?"Deposit Based":"Commission Based")+" user card created")}
function editUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox"><div class="modalHead"><div><b>Edit User / Mode</b><div class="muted" style="font-size:12px">Admin can configure remaining card details after creation.</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="form">'+field("User Name","uName",u.name)+field("Telegram Username","uTg",u.telegram)+field("UPI ID","uUpi",u.upi)+field("Mobile Number","uMob",u.mobile)+field("APK Mobile Number","uApk",u.apk)+field("GPay Login ID","uGpayLogin",u.gpayLogin)+selectField("Funding Model","uMode",[["commission","Commission Based — 3.5%"],["deposit","Deposit Based — USDT prepaid"]],u.fundingMode)+field("Admin Maximum Limit (Commission Mode)","uLimit",u.limit,"number")+field("Unique TRC20 Deposit Address (optional)","uDepositAddress",u.depositAddress||"")+'<div class="field full"><div class="notice">Deposit users use the unique address above when set; otherwise the global Admin TRC20 address is used. For production auto-matching, a unique address per user is recommended.</div></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveUser(\''+uid+'\')">Save User</button></div></div>')}
async function saveUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;var before=JSON.stringify({name:u.name,telegram:u.telegram,mode:u.fundingMode,limit:u.limit,addr:u.depositAddress});var draft={...u,name:v("uName"),telegram:v("uTg"),upi:v("uUpi"),mobile:v("uMob"),apk:v("uApk"),gpayLogin:v("uGpayLogin"),fundingMode:v("uMode")||"commission",limit:Math.max(0,Number(v("uLimit")||0)),depositAddress:v("uDepositAddress")};if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{var result=await backend.upsertProvider(draft);if(Number(result.data?.commission_limit_inr||0)!==draft.limit)throw new Error("Limit was not persisted");audit("user_updated",uid,"Before: "+before,"admin");close();await refreshFromBackend();toast("User updated")}catch(err){toast(err.message||"User update failed")}return}Object.assign(u,draft);audit("user_updated",uid,"Before: "+before,"admin");close();save();toast("User updated")}
function statusNotice(u){return u.status==="paused"?'<div class="notice amber" style="margin:15px 0"><b>ACCOUNT PAUSED</b><br>Reason: '+esc(u.pauseReason||"Temporarily unavailable")+'</div>':''}
function adminStatusButtons(u){if(staffRole!=="admin")return "";if(u.status==="deleted"||u.active===false)return '<button class="btn green sm" onclick="SF.resumeUser(\''+u.id+'\')">Restore</button>';return u.status==="paused"?'<button class="btn amber sm" onclick="SF.resumeUser(\''+u.id+'\')">Resume</button><button class="btn red sm" onclick="SF.deleteUser(\''+u.id+'\')">Delete</button>':'<button class="btn amber sm" onclick="SF.pauseUser(\''+u.id+'\')">Pause</button><button class="btn red sm" onclick="SF.deleteUser(\''+u.id+'\')">Delete</button>'}
function pauseUser(uid){if(staffRole!=="admin")return toast("Admin permission required");var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox small"><div class="modalHead"><b>Pause User</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="muted">User: '+esc(u.name)+'<br>User ID: '+esc(u.id)+'</div><div class="field" style="margin-top:14px"><label>Reason for pause</label><textarea id="pauseReason" rows="4"></textarea></div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.close()">Cancel</button><button class="btn amber" onclick="SF.confirmPause(\''+uid+'\')">Pause User</button></div></div>')}
async function confirmPause(uid){var reason=v("pauseReason");if(!reason)return toast("Pause reason is required");return changeProviderStatus(uid,"pause",reason)}
function deleteUser(uid){if(staffRole!=="admin")return toast("Admin permission required");var u=db.users.find(function(x){return x.id===uid});if(!u)return;modal('<div class="modalBox small"><div class="modalHead"><b>Delete User Permanently From Operations?</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="muted">User: '+esc(u.name)+'<br>User ID: '+esc(u.id)+'</div><div class="notice amber" style="margin-top:14px">This user will no longer be available for operations. Financial and audit history will be preserved.</div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.close()">Cancel</button><button class="btn red" onclick="SF.confirmDelete(\''+uid+'\')">Delete User</button></div></div>')}
async function confirmDelete(uid){return changeProviderStatus(uid,"delete","")}
async function resumeUser(uid){if(staffRole!=="admin")return toast("Admin permission required");return changeProviderStatus(uid,"resume","")}
async function changeProviderStatus(uid,action,reason){var u=db.users.find(function(x){return x.id===uid});if(!u)return;try{if(backend.configured&&u.remoteId){await backend.updateProviderStatus(u.remoteId,action,reason);close();toast(action==="pause"?"User paused":action==="delete"?"User deleted":"User resumed");await refreshFromBackend()}else{u.status=action==="pause"?"paused":action==="delete"?"deleted":"active";u.active=u.status!=="deleted";u.pauseReason=action==="pause"?reason:"";audit(action==="pause"?"provider_paused":action==="delete"?"provider_deleted":"provider_resumed",uid,reason||"","admin");close();save();toast(action==="pause"?"User paused":action==="delete"?"User deleted":"User resumed")}}catch(err){toast(err.message||"Provider status update failed")}}
function setCommissionLimit(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;if(u.fundingMode!=="commission")return toast("Maximum limit applies only to Commission Based users");var c=calc(u);modal('<div class="modalBox small"><div class="modalHead"><div><b>Set Commission User Limit</b><div class="muted" style="font-size:12px">Admin-only capacity control for '+esc(u.name)+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody">'+field("Maximum Collection Limit INR","commissionLimit",u.limit,"number")+'<div class="notice" style="margin-top:12px">Current collection: <b>'+money(c.collection)+'</b><br>Successful withdrawal: <b>'+money(c.inrReceived)+'</b><br>Current available: <b>'+money(c.collectionCapacity)+'</b><br><br>This limit is never shown to Merchant, Agent or the User.</div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveCommissionLimit(\''+uid+'\')">Save Limit</button></div></div>')}
async function saveCommissionLimit(uid){var u=db.users.find(function(x){return x.id===uid});if(!u||u.fundingMode!=="commission")return;var n=Number(v("commissionLimit")||0);if(n<0)return toast("Enter a valid limit");var old=Number(u.limit||0),draft={...u,limit:n};if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{var result=await backend.upsertProvider(draft);if(Number(result.data?.commission_limit_inr||0)!==n)throw new Error("Limit was not persisted");audit("commission_limit_updated",uid,"From "+money(old)+" to "+money(n),"admin");close();await refreshFromBackend();toast("Commission user limit updated")}catch(err){toast(err.message||"Commission limit update failed")}return}u.limit=n;audit("commission_limit_updated",uid,"From "+money(old)+" to "+money(n),"admin");close();save();toast("Commission user limit updated")}
function settings(){modal('<div class="modalBox"><div class="modalHead"><div><b>System Settings</b><div class="muted" style="font-size:12px">Settlement, deposit credit, commission and TRON watcher configuration.</div></div><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><h3>Security & Password</h3><div class="form">'+field("New Password","adminNewPassword","","password")+field("Confirm New Password","adminConfirmPassword","","password")+'<div class="field full"><button class="btn primary" type="button" onclick="SF.resetAdminPassword()">Reset Password</button><div class="notice">Authenticated Admin session is required. The current password is not required, and plaintext passwords are not stored.</div></div></div><h3>System Settings</h3><div class="form">'+field("Merchant Settlement Rate INR / USDT","sSettlement",db.settings.settlementRate,"number")+field("Deposit Base Rate INR / USDT","sBase",db.settings.depositBaseRate,"number")+field("Deposit Markup %","sMarkup",db.settings.depositMarkupPct,"number")+field("Commission % on Successful INR Withdrawal","sCommission",db.settings.commissionRate,"number")+field("Global Admin TRC20 Address","sAddress",db.settings.adminTrc20Address)+field("TRON USDT Contract","sContract",db.settings.usdtContract||USDT_CONTRACT)+ '<div class="field"><label>Calculated Deposit Rate</label><input disabled value="'+money(depositRate())+' / USDT"></div><div class="field full"><div class="notice amber"><b>Production security:</b> do not expose TronGrid API keys, GPay encryption keys or service-role keys in browser code. Run the blockchain watcher and credential decryption on a trusted backend/worker.</div></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveSettings()">Save Settings</button></div></div>')}
async function saveSettings(){var next={settlementRate:Math.max(.01,Number(v("sSettlement")||107)),depositBaseRate:Math.max(.01,Number(v("sBase")||107)),depositMarkupPct:Math.max(0,Number(v("sMarkup")||3)),commissionRate:Math.max(0,Number(v("sCommission")||3.5)),adminTrc20Address:v("sAddress"),usdtContract:v("sContract")||USDT_CONTRACT};if(JSON.stringify(next)===JSON.stringify(db.settings))return toast("No settings changes");if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{await backend.writeSettings(next);db.settings=next;audit("settings_updated","","Rates / TRON settings updated","admin");close();toast("Settings saved");await refreshFromBackend()}catch(err){toast(err.message||"Settings update failed")}return}db.settings=next;audit("settings_updated","","Rates / TRON settings updated","admin");close();save();toast("Settings saved")}
async function resetAdminPassword(){var p=v("adminNewPassword"),c=v("adminConfirmPassword");if(!backend.configured)return toast("Password reset requires Supabase Auth");if(!p||p.length<10)return toast("Use at least 10 characters");if(p!==c)return toast("Passwords do not match");try{await backend.updateAdminPassword(p);document.getElementById("adminNewPassword").value="";document.getElementById("adminConfirmPassword").value="";toast("Admin password reset")}catch(err){toast(err.message||"Password reset failed")}}
