async function updateEntry(eid){var e=db.entries.find(function(x){return x.id===eid}),u=e&&db.users.find(function(x){return x.id===e.userId});if(!e||!u)return;var draft={...e,date:v("eeDate"),note:v("eeNote"),status:v("eeStatus")||e.status,reason:v("eeReason")};if(e.type==="collection"||e.type==="inr_received"||e.type==="frozen")draft.amount=Math.max(0,Number(v("eeAmount")||0));if(e.type==="collection"){draft.bank=v("eeBank");draft.account=v("eeAccount");draft.accountId=v("eeAccountId")}if(e.type==="inr_received")draft.accountId=v("eeAccountId");if(e.type==="frozen")draft.bank=v("eeBank");if(e.type==="user_usdt"||e.type==="merchant_usdt"){draft.usdt=Math.max(0,Number(v("eeUsdt")||0));draft.rate=Math.max(.01,Number(v("eeRate")||db.settings.settlementRate))}if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{await backend.adminUpdateLedger(draft,u.remoteId);close();toast("Correction saved");await refreshFromBackend()}catch(err){toast(err.message||"Ledger correction failed")}return}Object.assign(e,draft,{editedAt:nowIso(),editReason:draft.reason});audit("ledger_corrected",e.userId,label(e.type)+" corrected","admin");close();save();toast("Correction saved")}
async function release(eid){var e=db.entries.find(function(x){return x.id===eid}),u=e&&db.users.find(function(x){return x.id===e.userId});if(!e||!u)return;if(backend.configured){if(!backendStateReady)return toast("Backend is still loading; try again");try{await backend.releaseLedger(e.id,u.remoteId);close();toast("Frozen amount released");await refreshFromBackend()}catch(err){toast(err.message||"Frozen release failed")}return}e.status="released";e.releaseDate=today();e.updatedAt=nowIso();audit("frozen_released",e.userId,money(e.amount),"admin");close();save();toast("Frozen amount released")}
function viewEntry(eid){var e=db.entries.find(function(x){return x.id===eid}),u=e&&db.users.find(function(x){return x.id===e.userId}),a=(u?.upiAccounts||[]).find(function(x){return x.id===e.accountId});if(!e)return;modal('<div class="modalBox small"><div class="modalHead"><b>Transaction Detail</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="detailKpis">'+metric("ID",esc(e.id))+metric("User",esc(u?.name||e.userId))+metric("UPI",esc(a?.label||"Legacy / Unassigned"))+metric("Type",esc(label(e.type)))+metric("Amount",e.usdt?usdt(e.usdt):money(e.amount))+metric("Date",dateFmt(e.date))+metric("Status",esc(e.isVoided?"Voided":e.status||"posted"))+metric("Edited",esc(e.editedAt?dateFmt(e.editedAt):"-"))+'</div><div class="notice">'+esc(e.note||"No note")+(e.voidReason?'<br>Void reason: '+esc(e.voidReason):'')+'</div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.editEntry(\''+eid+'\')">Edit</button>'+(e.isVoided?'':'<button class="btn red" onclick="SF.voidEntry(\''+eid+'\')">Void</button>')+'</div></div>')}
function voidEntry(eid){var e=db.entries.find(function(x){return x.id===eid});if(!e||e.isVoided)return;modal('<div class="modalBox small"><div class="modalHead"><b>Void Transaction</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="notice amber">This keeps the row for audit but removes it from current balances.</div><div class="field"><label>Void Reason</label><textarea id="voidReason" rows="4"></textarea></div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.close()">Cancel</button><button class="btn red" onclick="SF.confirmVoidEntry(\''+eid+'\')">Void</button></div></div>')}
async function confirmVoidEntry(eid){var reason=v("voidReason");if(!reason)return toast("Void reason required");try{if(backend.configured){await backend.adminVoidLedger(eid,reason);close();await refreshFromBackend();toast("Transaction voided");return}var e=db.entries.find(function(x){return x.id===eid});Object.assign(e,{isVoided:true,status:"reversed",voidedAt:nowIso(),voidReason:reason});audit("ledger_entry_voided",e.userId,reason,"admin");close();save();toast("Transaction voided")}catch(err){toast(err.message||"Void failed")}}
function withdrawalRow(w,adminMode){var u=db.users.find(function(x){return x.id===w.userId}),a=(u?.upiAccounts||[]).find(function(x){return x.id===w.accountId}),status=w.isVoided?"Voided":w.status;return '<div class="listRow"><div><b>'+esc(w.requesterType==="merchant"?"Merchant Withdrawal":"User Commission Withdrawal")+' · '+usdt(w.amountUsdt)+' / '+money(w.amountInr)+'</b><div class="muted">'+esc(w.requesterType==="merchant"?"Merchant":(u?.name||w.userId||""))+' · '+esc(a?.label||w.address||"")+'</div></div><div><span class="badge '+(w.isVoided?'red':'')+'">'+esc(status)+'</span><div class="muted">'+dateFmt(w.paidAt||w.createdAt)+' · '+esc(w.proofTxHash||w.proofNote||"")+'</div>'+(w.editedAt?'<div class="auditLine">Edited '+dateFmt(w.editedAt)+' '+esc(w.editReason||"")+'</div>':'')+(w.isVoided?'<div class="auditLine">Voided '+dateFmt(w.voidedAt)+' '+esc(w.voidReason||"")+'</div>':'')+'</div><div class="cardActions">'+(adminMode?'<button class="btn ghost sm" onclick="SF.viewWithdrawal(\''+w.id+'\')">View</button><button class="btn ghost sm" onclick="SF.editWithdrawal(\''+w.id+'\')">Edit</button>'+(w.isVoided?'':'<button class="btn red sm" onclick="SF.voidWithdrawal(\''+w.id+'\')">Void</button>'):'')+(w.status==="pending"&&!w.isVoided?'<button class="btn primary sm" onclick="SF.markWithdrawal(\''+w.id+'\')">Mark Paid</button>':'')+'</div></div>'}
function viewWithdrawal(idv){var w=db.withdrawals.find(function(x){return x.id===idv}),u=w&&db.users.find(function(x){return x.id===w.userId}),a=(u?.upiAccounts||[]).find(function(x){return x.id===w.accountId});if(!w)return;modal('<div class="modalBox small"><div class="modalHead"><b>Withdrawal Detail</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="detailKpis">'+metric("ID",esc(w.id))+metric("Requester",esc(w.requesterType))+metric("User",esc(u?.name||w.userId||"Merchant"))+metric("UPI",esc(a?.label||"Unassigned"))+metric("Amount",usdt(w.amountUsdt)+" / "+money(w.amountInr))+metric("Rate",money(w.rate))+metric("Status",esc(w.isVoided?"Voided":w.status))+metric("Edited",esc(w.editedAt?dateFmt(w.editedAt):"-"))+'</div><div class="notice">'+esc(w.address||"")+(w.voidReason?'<br>Void reason: '+esc(w.voidReason):'')+'</div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.editWithdrawal(\''+idv+'\')">Edit</button>'+(w.isVoided?'':'<button class="btn red" onclick="SF.voidWithdrawal(\''+idv+'\')">Void</button>')+'</div></div>')}
function editWithdrawal(idv){var w=db.withdrawals.find(function(x){return x.id===idv}),u=w&&db.users.find(function(x){return x.id===w.userId}),opts=[["","Unassigned"]].concat(((u&&u.upiAccounts)||[]).map(function(a){return [a.id,(a.label||"UPI")+" · "+(a.upi||"")] }));if(!w||w.isVoided)return;modal('<div class="modalBox"><div class="modalHead"><b>Edit Withdrawal</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+field("USDT Amount","wwUsdt",w.amountUsdt,"number")+field("Rate","wwRate",w.rate||107,"number")+field("Destination Address","wwAddress",w.address||"")+selectField("Status","wwStatus",[["pending","Pending"],["paid","Paid"],["rejected","Rejected"],["cancelled","Cancelled"]],w.status||"pending")+selectField("UPI Account","wwAccountId",opts,w.accountId||"")+field("Proof TX Hash","wwHash",w.proofTxHash||"")+field("Proof URL","wwUrl",w.proofUrl||"")+'<div class="field full"><label>Proof Note</label><input id="wwNote" value="'+esc(w.proofNote||"")+'"></div><div class="field full"><label>Edit Reason</label><input id="wwReason"></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.updateWithdrawal(\''+idv+'\')">Save Correction</button></div></div>')}
async function updateWithdrawal(idv){var w=db.withdrawals.find(function(x){return x.id===idv});if(!w)return;try{await backend.adminUpdateWithdrawal({id:idv,accountId:v("wwAccountId"),amountUsdt:Number(v("wwUsdt")||0),rate:Number(v("wwRate")||107),address:v("wwAddress"),status:v("wwStatus"),proofTxHash:v("wwHash"),proofUrl:v("wwUrl"),proofNote:v("wwNote"),reason:v("wwReason")});close();await refreshFromBackend();toast("Withdrawal corrected")}catch(err){toast(err.message||"Withdrawal correction failed")}}
function voidWithdrawal(idv){var w=db.withdrawals.find(function(x){return x.id===idv});if(!w||w.isVoided)return;modal('<div class="modalBox small"><div class="modalHead"><b>Void Withdrawal</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="notice amber">This preserves the withdrawal for audit and removes it from balances.</div><div class="field"><label>Void Reason</label><textarea id="voidReason" rows="4"></textarea></div></div><div class="modalFoot"><button class="btn ghost" onclick="SF.close()">Cancel</button><button class="btn red" onclick="SF.confirmVoidWithdrawal(\''+idv+'\')">Void</button></div></div>')}
async function confirmVoidWithdrawal(idv){var reason=v("voidReason");if(!reason)return toast("Void reason required");try{await backend.adminVoidWithdrawal(idv,reason);close();await refreshFromBackend();toast("Withdrawal voided")}catch(err){toast(err.message||"Void failed")}}
function depositRow(d,adminMode){return '<div class="entry"><div><b>TRC20 Deposit</b><div class="muted" style="font-size:10px">'+dateFmt(d.createdAt)+'</div></div><div><b>'+usdt(d.requestedUsdt)+' → '+money(d.inrValue)+'</b><div class="muted" style="font-size:11px">Rate '+money(d.rate)+' • '+esc(d.address||"No address")+'</div><div class="auditLine"><span class="statusDot '+(d.status==="confirmed"?'confirmed':d.status==="failed"?'failed':'')+'"></span>'+esc(d.status)+' '+(d.txHash?'• '+esc(d.txHash):'')+'</div></div><div>'+(adminMode&&d.status!=="confirmed"?'<button class="btn ghost sm" onclick="SF.checkDeposit(\''+d.id+'\',true)">Check</button> <button class="btn green sm" onclick="SF.simulateConfirm(\''+d.id+'\')">Demo Confirm</button>':'<span class="badge '+(d.status==="confirmed"?'green':'amber')+'">'+esc(d.status)+'</span>')+'</div></div>'}
function createDepositPage(uid){var u=db.users.find(function(x){return x.id===uid});if(!u||u.fundingMode!=="deposit")return toast("Deposit mode required");var addr=u.depositAddress||db.settings.adminTrc20Address||"";modal('<div class="modalBox"><div class="modalHead"><div><b>Create USDT Deposit</b><div class="muted" style="font-size:12px">TRC20 • 1 USDT = '+money(depositRate())+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="depositHero"><div class="depositPanel"><h2 style="margin-top:0">Enter Deposit Amount</h2>'+field("USDT Amount","depAmount","","number")+'<div class="notice green" style="margin-top:12px">Every confirmed 1 USDT adds <b>'+money(depositRate())+'</b> to your collection balance.</div><div class="cardActions"><button class="btn primary" onclick="SF.generateDeposit(\''+uid+'\')">Generate Deposit QR</button></div><div class="securityNote">Blockchain confirmation is automatic when the watcher can query TronGrid. This standalone prototype also includes a Demo Confirm button for testing.</div></div><div class="depositPanel depositQR"><div style="text-align:center"><div class="muted">Deposit address</div><div style="font-size:13px;margin-top:8px;word-break:break-all">'+esc(addr||"Admin has not configured a TRC20 address yet.")+'</div></div></div></div></div></div>')}
async function generateDeposit(uid){var u=db.users.find(function(x){return x.id===uid}),amount=Number(v("depAmount")||0);if(amount<=0)return toast("Enter valid USDT amount");if(backend.configured&&currentSharedRole==="User"){try{var result=await backend.shareAction(location.hash.split("=")[1],{action:"deposit",amount_usdt:amount});toast("Deposit request created");var remote=await backend.resolveShare(location.hash.split("=")[1]);db=remote.state;showDepositRequest(result.data.id)}catch(err){toast(err.message||"Deposit request failed")}return}var addr=u.depositAddress||db.settings.adminTrc20Address||"";if(!addr)return toast("Admin must configure a TRC20 address first");var rate=depositRate(),d={id:id("dep"),userId:uid,requestedUsdt:amount,expectedUsdt:amount,rate:rate,inrValue:amount*rate,address:addr,status:"waiting",txHash:"",createdAt:nowIso(),confirmedAt:"",source:"user"};db.deposits.push(d);audit("deposit_created",uid,usdt(amount)+" at "+money(rate),"user");save(true);showDepositRequest(d.id)}
function paymentPayload(d){return "USDT TRC20\nAddress: "+d.address+"\nAmount: "+Number(d.expectedUsdt).toFixed(6)}
function qrUrl(d){return "https://quickchart.io/qr?size=320&text="+encodeURIComponent(paymentPayload(d))}
function showDepositRequest(did){var d=db.deposits.find(function(x){return x.id===did}),u=db.users.find(function(x){return x.id===d.userId});if(!d)return;modal('<div class="modalBox"><div class="modalHead"><div><b>Deposit Request</b><div class="muted" style="font-size:12px">'+esc(u?u.name:d.userId)+' • '+esc(d.id)+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody"><div class="depositHero"><div class="depositPanel"><div class="muted">Send exactly</div><div class="depositAmount">'+usdt(d.expectedUsdt)+'</div><div class="muted">Credit after confirmation</div><div style="font-size:22px;font-weight:900;margin:5px 0 16px">'+money(d.inrValue)+'</div><div class="addressBox">'+esc(d.address)+'</div><div class="cardActions"><button class="btn ghost" onclick="SF.copy(\''+esc(d.address)+'\',\'Address copied\')">Copy Address</button><button class="btn ghost" onclick="SF.copy(\''+d.expectedUsdt+'\',\'Amount copied\')">Copy Amount</button></div><div class="notice" style="margin-top:14px"><span class="statusDot '+(d.status==="confirmed"?'confirmed':'')+'"></span>Status: <b>'+esc(d.status.toUpperCase())+'</b>'+(d.txHash?'<br>TX: '+esc(d.txHash):'')+'</div><div class="cardActions"><button class="btn blue" onclick="SF.checkDeposit(\''+d.id+'\',true)">Check Blockchain</button>'+(d.status!=="confirmed"?'<button class="btn green" onclick="SF.simulateConfirm(\''+d.id+'\')">Demo Confirm</button>':'')+'</div></div><div class="depositPanel depositQR"><div><img src="'+qrUrl(d)+'" alt="Deposit QR"><div class="muted" style="text-align:center;margin-top:10px">TRC20 deposit QR</div></div></div></div></div></div>')}
function checkDeposit(did,manual){if(manual)toast("Blockchain confirmation requires the backend watcher; use Demo Confirm for local testing")}
function checkAllDeposits(manual){db.deposits.filter(function(d){return d.status!=="confirmed"}).forEach(function(d){checkDeposit(d.id,false)});if(manual)toast("Blockchain checks started")}
function simulateConfirm(did){var d=db.deposits.find(function(x){return x.id===did});if(!d||d.status==="confirmed")return;d.status="confirmed";d.txHash="DEMO_"+id("tx");d.confirmedAt=nowIso();d.source="demo";audit("deposit_confirmed_demo",d.userId,usdt(d.expectedUsdt),"demo");close();save();toast("Demo deposit confirmed")}
function simulateConfirm(did){if(backend.configured)return toast("Demo confirmation is disabled in production");var d=db.deposits.find(function(x){return x.id===did});if(!d||d.status==="confirmed")return;d.status="confirmed";d.txHash="DEMO_"+id("tx");d.confirmedAt=nowIso();d.source="demo";audit("deposit_confirmed_demo",d.userId,usdt(d.expectedUsdt),"demo");close();save();toast("Demo deposit confirmed")}
function startWatcher(){}
async function regen(kind){if(backend.configured){try{var result=await backend.callFunction("share-link",{action:"regenerate",scope:kind});var token=result.data&&result.data[0]&&result.data[0].token;if(!token)throw new Error("share token was not returned");backend.rememberShareToken(kind,"",token);if(kind==="merchant")db.settings.merchantToken=token;else db.settings.agentToken=token;toast(kind+" link regenerated");render()}catch(err){toast(err.message||"Share link failed")}}else{if(kind==="merchant")db.settings.merchantToken=tok();else db.settings.agentToken=tok();audit("share_regenerated","",kind,"admin");save();toast(kind+" link regenerated")}}
async function regenUser(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;if(backend.configured&&u.remoteId){try{var result=await backend.callFunction("share-link",{action:"regenerate",scope:"user",provider_id:u.remoteId});u.token=result.data&&result.data[0]&&result.data[0].token;if(!u.token)throw new Error("share token was not returned");backend.rememberShareToken("user",u.remoteId,u.token);toast("User link regenerated");render()}catch(err){toast(err.message||"Share link failed")}}else{u.token=tok();audit("user_share_regenerated",uid,"Individual link regenerated","admin");save();toast("User link regenerated")}}
function copyUser(uid){var u=db.users.find(function(x){return x.id===uid});if(u)copy(userLink(u),"User link copied")}
var currentSharedRole="";
function sharedDashboard(tokn,role){currentSharedRole=role;var expected=role==="Agent"?db.settings.agentToken:db.settings.merchantToken;if(tokn!==expected)return invalid(role+" link is invalid or revoked.");var t=totals(),visible=db.users.filter(function(u){return u.status!=="deleted"&&u.active!==false}).length,kpis=role==="Merchant"?kpi("TOTAL COLLECTION",money(t.collection),"All visible cards")+kpi("AVAILABLE LIMIT",money(t.capacity),"Remaining capacity")+kpi("USERS",visible,"Visible cards"):kpi("TOTAL COLLECTION",money(t.collection),"All visible cards")+kpi("AVAILABLE LIMIT",money(t.capacity),"Remaining capacity")+kpi("FROZEN",money(t.frozen),"Current")+kpi("USERS",visible,"Visible cards");document.getElementById("app").innerHTML='<div class="readonly"><div class="readHead"><div class="logo"><div class="logoMark">◆</div><div>'+role+' Live Dashboard<div class="muted" style="font-size:11px">'+(role==="Merchant"?'GPay access + collection write':'Read-only GPay access')+'</div></div></div><span class="badge green">● Live</span></div><div class="notice">'+(role==="Merchant"?'Merchant can add Collection and correct Collection Amount only. Available Limit is enforced per card.':'Agent is read-only. GPay credentials and QR codes are visible where permitted.')+'</div><div class="kpis" style="margin-top:15px">'+kpis+'</div><div class="toolbar"><div><h2>User Cards</h2><div class="muted">Available limit shown without exposing admin-only configured maximums.</div></div><input class="search" placeholder="Search..." oninput="SF.mSearch(this.value)"></div><div id="mCards" class="grid"></div></div>';mSearch("")}
function merchant(t){sharedDashboard(t,"Merchant")}function agent(t){sharedDashboard(t,"Agent")}function mSearch(q){q=(q||"").toLowerCase();var arr=db.users.filter(function(u){return u.status!=="deleted"&&u.active!==false&&(u.name+" "+u.upi+" "+u.mobile).toLowerCase().indexOf(q)>-1});document.getElementById("mCards").innerHTML=arr.map(function(u){return card(u,true)}).join("")}
function readDetail(uid){var u=db.users.find(function(x){return x.id===uid});if(!u)return;var c=calc(u),es=entries(uid).filter(function(e){return e.type==="collection"}).slice().sort(function(a,b){return String(b.date||"").localeCompare(String(a.date||""))});var merchantControls=currentSharedRole==="Merchant"?'<div class="cardActions" style="margin:16px 0"><button class="btn primary" '+(u.status==="paused"?"disabled":"")+' onclick="SF.merchantAddCollection(\''+uid+'\')">+ Add Collection</button><span class="muted" style="font-size:11px">Available Limit now: '+money(c.collectionCapacity)+'</span></div>':'';modal('<div class="modalBox"><div class="modalHead"><div><b>'+esc(u.name)+'</b><div class="muted" style="font-size:12px">'+esc(u.id)+' • '+esc(u.upi||"UPI not added")+' • APK: '+esc(u.apk||u.mobile||"Not added")+'</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody">'+statusNotice(u)+'<div class="detailKpis">'+metric("Total Collection",money(c.collection))+metric("Available Limit",money(c.collectionCapacity))+metric("UPI ID",esc(u.upi||"-"))+metric("APK / Mobile",esc(u.apk||u.mobile||"-"))+'</div>'+merchantControls+'<h3>Google Pay Details</h3><div class="notice">Only operational GPay details, total collection and available limit are shown here. Funding model, admin limit, deposit amounts, deposit history, commission, withdrawals, frozen funds and internal settlement data are private.</div><div class="credGrid"><div class="credBox"><span>UPI ID</span><div class="credValue"><code>'+esc(u.upi||"-")+'</code></div></div><div class="credBox"><span>APK / Mobile Number</span><div class="credValue"><code>'+esc(u.apk||u.mobile||"-")+'</code></div></div></div>'+credentialHTML(u,true)+'<h3>GPay QR Codes</h3>'+qrHTML(u,false)+'<h3>Collection History</h3>'+(es.length?es.map(function(e){var row=entryRow(e,false);if(e.type==="collection"&&currentSharedRole==="Merchant")row+='<div class="cardActions" style="margin:-8px 0 10px"><button class="btn ghost sm" onclick="SF.editCollectionAmount(\''+e.id+'\')">Edit Collection Amount</button></div>';return row}).join(""):'<div class="empty">No collection history</div>')+'</div></div>')}
function merchantAddCollection(uid){if(currentSharedRole!=="Merchant")return toast("Merchant permission required");openCollectionForm(uid,"merchant")}
function editCollectionAmount(eid){if(currentSharedRole!=="Merchant")return toast("Merchant permission required");var e=db.entries.find(function(x){return x.id===eid});if(!e||e.type!=="collection")return;modal('<div class="modalBox small"><div class="modalHead"><div><b>Edit Collection Amount</b><div class="muted" style="font-size:12px">Merchant can correct amount only.</div></div><button class="btn ghost sm" onclick="SF.close()">✕</button></div><div class="modalBody">'+field("Collection Amount","mcEdit",e.amount,"number")+'<div class="field" style="margin-top:12px"><label>Correction Note</label><input id="mcReason" placeholder="Optional reason"></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveCollectionAmount(\''+eid+'\')">Save Correction</button></div></div>')}
async function saveCollectionAmount(eid){if(currentSharedRole!=="Merchant")return toast("Merchant permission required");var e=db.entries.find(function(x){return x.id===eid}),u=e&&db.users.find(function(x){return x.id===e.userId});if(!e||!u)return;var old=Number(e.amount||0),n=Number(v("mcEdit")||0);if(n<0)return toast("Invalid amount");var c=calc(u),maxAllowed=c.collectionCapacity+old;if(n>maxAllowed+0.0001)return toast("Corrected amount exceeds available capacity: "+money(maxAllowed));var reason=v("mcReason"),note=e.note||"";if(reason)note=(note?note+" • ":"")+"Correction: "+reason;if(backend.configured){try{await backend.shareAction(location.hash.split("=")[1],{action:"collection_update",provider_id:u.remoteId,entry_id:e.id,amount_inr:n,note:note});var remote=await backend.resolveShare(location.hash.split("=")[1]);db=remote.state;close();render();toast("Collection amount corrected")}catch(err){toast(err.message||"Collection correction failed")}return}e.previousAmount=old;e.amount=n;e.updatedAt=nowIso();e.updatedBy="merchant";e.note=note;audit("collection_corrected",e.userId,"From "+money(old)+" to "+money(n),"merchant");close();save();toast("Collection amount corrected")}
