function manualMerchantSettlement(){var t=totals(),available=Math.max(0,t.collection-t.frozen-t.merchantSettled),rate=Number(db.settings.settlementRate||107);modal('<div class="modalBox" style="max-width:680px"><div class="modalHead"><div><b>Manual Merchant Settlement</b><div class="muted" style="font-size:12px">Available settlement '+money(available)+' @ '+money(rate)+'</div></div><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody"><div class="form">'+field("USDT Amount","merchantSettleUsdt","","number")+field("Settlement Rate","merchantSettleRate",rate,"number")+field("TRC20 Address","merchantSettleAddress","")+field("Transaction Hash","merchantSettleHash","")+field("Tronscan URL","merchantSettleUrl","")+'<div class="field full"><label>Proof / Note</label><input id="merchantSettleNote"></div></div></div><div class="modalFoot"><button class="btn primary" onclick="SF.saveManualMerchantSettlement()">Save Settlement</button></div></div>')}
