function accountRow(u,a,actions){var c=accountCalc(u,a),state=a.merchantOperational===false||a.status!=="active"?"STOPPED":"RUNNING",extra=actions||"";if(currentSharedRole==="Merchant")extra='<button class="btn primary sm" onclick="SF.merchantAccountCollection(\''+u.id+'\',\''+a.id+'\')">Add Collection</button><button class="btn ghost sm" onclick="SF.merchantRevealCredential(\''+u.remoteId+'\',\''+a.id+'\')">GPay Details</button><button class="btn amber sm" onclick="SF.merchantToggleUpi(\''+a.id+'\',\''+u.remoteId+'\')">'+(state==="RUNNING"?"Stop":"Start")+'</button>';if(currentSharedRole==="User")extra='<button class="btn ghost sm" onclick="SF.editPublicUpi(\''+a.id+'\')">Edit</button><button class="btn ghost sm" onclick="SF.publicUpiCredentials(\''+a.id+'\')">GPay</button><button class="btn ghost sm" onclick="SF.openQR(\''+a.id+'\')">QR</button>';return '<div class="card accountCard"><div class="cardHead"><div><h3>'+esc(u.name)+' · '+esc(a.label||"UPI")+'</h3><div class="meta">'+esc(u.id)+' · '+esc(a.upi||"No UPI")+' · '+esc(a.mobile||a.apk||"No mobile")+'</div></div><span class="badge '+(state==="RUNNING"?'green':'amber')+'">'+state+'</span></div><div class="metrics">'+metric("Total Collection",money(c.collection))+metric("Available Limit",money(c.available))+metric("Mobile / APK",esc(a.mobile||a.apk||"-"))+'</div><div class="cardActions">'+extra+'</div></div>'}
function openQR(aid){var x=accountById(aid);if(!x)return;var q=(x.a.qrs||[]);modal('<div class="modalBox small"><div class="modalHead"><b>QR · '+esc(x.a.label)+'</b><button class="btn ghost sm" onclick="SF.close()">Close</button></div><div class="modalBody">'+(q.map(function(item){return '<img src="'+esc(item.data||"")+'" alt="QR" style="width:100%;max-height:280px;object-fit:contain;background:#fff;border-radius:10px;margin-bottom:8px">'}).join("")||'<div class="empty">No QR uploaded</div>')+(currentSharedRole==="User"?'<input id="accountQrFile" type="file" accept="image/*"><button class="btn primary" onclick="SF.uploadAccountQR(\''+aid+'\')">Upload QR</button>':"")+'</div></div>')}
async function uploadAccountQR(aid){
var x=accountById(aid),file=document.getElementById("accountQrFile")?.files?.[0];if(!x||!file)return toast("Choose a QR image");
try{
if(currentSharedRole==="User"){
var data=await new Promise(function(resolve,reject){var reader=new FileReader();reader.onload=function(){resolve(reader.result)};reader.onerror=reject;reader.readAsDataURL(file)});
if(routeRole()==="user"){await portalAction({action:"qr_upload",upi_account_id:aid,data:data,display_name:file.name});close();await loadPortal("user");toast("QR uploaded");return}
var token=location.hash.split("=").slice(1).join("=");await backend.userUpiAction(token,{action:"qr_upload",upi_account_id:aid,data:data,display_name:file.name});close();var r=await backend.resolveShare(token);db=r.state;render();toast("QR uploaded");return}
await backend.uploadQR(x.u.remoteId,file,file.name,aid);close();await refreshFromBackend();toast("QR uploaded")
}catch(err){toast(err.message||"QR upload failed")}}
