function historyOffset(source,ctx,uid){if(source==="ledger"){var es=db.entries||[];if(ctx==="user")es=es.filter(function(e){return e.userId===uid});if(ctx==="merchant")es=es.filter(function(e){return e.type==="collection"});return es.length}if(source==="deposits"){var ds=db.deposits||[];return ctx==="user"?ds.filter(function(d){return d.userId===uid}).length:ds.length}if(source==="withdrawals"){var ws=db.withdrawals||[];if(ctx==="user")ws=ws.filter(function(w){return w.requesterType==="provider"&&w.userId===uid});if(ctx==="merchant")ws=ws.filter(function(w){return w.requesterType==="merchant"});return ws.length}if(source==="merchant_settlements")return (db.merchantSettlements||[]).length;if(source==="merchant_charges")return (db.merchantCharges||[]).length;return 0}
function historySources(ctx){return ctx==="user"?["ledger","deposits","withdrawals"]:ctx==="merchant"?["ledger","withdrawals","merchant_settlements","merchant_charges"]:["ledger","deposits","withdrawals","merchant_settlements","merchant_charges"]}
