async function portalLogin(role){try{var loginId=v("portalLoginId");if(role==="user")loginId=loginId.toUpperCase();var result=await backend.portalLogin(role,loginId,v("portalPassword"));setPortalSession(role,result.data.token);await loadPortal(role)}catch(err){portalLoginScreen(role,err.message||"Invalid login credentials")}}
async function loadPortal(role){var s=portalSession(role);if(!s.token)return portalLoginScreen(role);try{var result=await backend.portalResolve(role,s.token);setPortalSession(role,s.token);db=result.state;currentSharedRole=portalLabel(role);if(role==="user"){var u=db.users[0];if(u&&u.status!=="deleted"&&u.active!==false){u.token="portal";window.__publicUserId=u.id;return userView("portal")}throw new Error("User account is unavailable.")}else if(role==="merchant"){db.settings.merchantToken="portal";sharedDashboard("portal","Merchant")}else if(role==="agent"){db.settings.agentToken="portal";sharedDashboard("portal","Agent")}}catch(err){clearPortalSession(role);portalLoginScreen(role,err.message||"Access denied")}}
